"""##

    private static let translations: [String: [String: String]] = {
        // 1. Try to dynamically load Localizable.xcstrings if bundled as resource
        if let url = Bundle.main.url(forResource: "Localizable", withExtension: "xcstrings"),
           let data = try? Data(contentsOf: url),
           let parsed = parseXCStrings(data: data) {
            return parsed
        }
        
        // 2. Fast decode from embedded JSON data
        if let data = embeddedJSON.data(using: .utf8),
           let decoded = try? JSONSerialization.jsonObject(with: data) as? [String: [String: String]] {
            return decoded
        }
        
        return [:]
    }()

    public static func string(for key: String, language: String) -> String? {
        translations[language]?[key]
    }
    
    private static func parseXCStrings(data: Data) -> [String: [String: String]]? {
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let strings = json["strings"] as? [String: [String: Any]] else {
            return nil
        }
        
        var result: [String: [String: String]] = [:]
        for (key, val) in strings {
            guard let locs = val["localizations"] as? [String: [String: Any]] else { continue }
            for (lang, unit) in locs {
                if let strUnit = unit["stringUnit"] as? [String: Any],
                   let value = strUnit["value"] as? String {
                    if result[lang] == nil {
                        result[lang] = [:]
                    }
                    result[lang]?[key] = value
                }
            }
        }
        return result
    }
}
